    private static void nodeJar(ServerLevel level,ServerPlayer player,BiConsumer<Boolean,String> c){
        var p=O.offset(0,2,0);var node=node(level,p,Map.of("aer",45,"ignis",20,"auram",12),NodeState.Type.PURE,NodeState.Modifier.BRIGHT);node.state.base.put("aer",60);var id=node.id();
        for(var pos:NodeJarActions.shell(p))level.setBlockAndUpdate(pos,(pos.getY()==p.getY()+2?Blocks.OAK_SLAB:Blocks.GLASS).defaultBlockState());
        var wand=wand();player.setItemInHand(InteractionHand.MAIN_HAND,wand);
        var hole=p.north();level.removeBlock(hole,false);c.accept(!NodeJarActions.fits(level,p)&&!NodeJarActions.pack(player,wand,p.north()),"node jar refuses an incomplete glass/slab structure without spending vis");level.setBlockAndUpdate(hole,Blocks.GLASS.defaultBlockState());
        KnowledgeService.mutate(player,k->k.completeResearch("NODEJAR"));WandVis.set(wand,Aspects.FIRE,0);
        c.accept(!NodeJarActions.pack(player,wand,p.north())&&WandVis.get(wand,Aspects.AIR)==10000&&level.getBlockEntity(p)==node,"node jar requires all six costs atomically");
        WandVis.set(wand,Aspects.FIRE,10000);level.random.setSeed(1);
        c.accept(wand.getItem().useOn(new UseOnContext(player,InteractionHand.MAIN_HAND,new BlockHitResult(p.north().getCenter(),Direction.NORTH,p.north(),false))).consumesAction(),"wand click on shell invokes actual node packaging");
        var jar=(JarredNodeBlockEntity)level.getBlockEntity(p);c.accept(jar!=null&&jar.id().equals(id)&&jar.state.type==NodeState.Type.PURE&&jar.state.current.equals(node.state.current)&&jar.state.base.get("aer")==45,"jar preserves identity/type/current vis and resets depleted base to captured amount like TC4");
        c.accept(jar.state.modifier==NodeState.Modifier.NONE,"seeded original 75 percent packaging roll reduces BRIGHT by one tier");
        c.accept(NodeJarActions.shell(p).stream().allMatch(level::isEmptyBlock),"packaging consumes exactly the 35 shell blocks");
        for(var a:Aspects.PRIMALS)c.accept(WandVis.get(wand,a)==10000-WandVis.cost(wand,Map.of(a.getTag(),70),player).get(a),"node jar charges discounted 70 vis for "+a.getTag());
        var packed=jar.item();var parsed=ItemStack.parseOptional(level.registryAccess(),(CompoundTag)packed.save(level.registryAccess()));c.accept(ItemStack.matches(packed,parsed),"jar node data survives native ItemStack codec");
        var before=jar.state.current.toString();for(int i=0;i<2400;i++)if(jar.getBlockState().getTicker(level,jar.getType())!=null)throw new AssertionError("Frozen jar unexpectedly has a ticker");c.accept(before.equals(jar.state.current.toString()),"jar has no recharge, exhaust damage or natural node effects ticker");
        var drops=Block.getDrops(jar.getBlockState(),level,p,jar,player,new ItemStack(Items.DIAMOND_PICKAXE));c.accept(drops.size()==1&&ItemStack.matches(drops.getFirst(),packed),"breaking jar drops exactly one item retaining node state");
        level.removeBlock(p,false);player.setItemInHand(InteractionHand.MAIN_HAND,parsed);var place=new UseOnContext(player,InteractionHand.MAIN_HAND,new BlockHitResult(p.below().getCenter(),Direction.UP,p.below(),false));level.setBlockAndUpdate(p.below(),Blocks.STONE.defaultBlockState());player.setItemInHand(InteractionHand.MAIN_HAND,parsed);c.accept(parsed.getItem().useOn(place).consumesAction(),"native block-item placement restores jar from its components");
        jar=(JarredNodeBlockEntity)level.getBlockEntity(p);c.accept(jar.id().equals(id)&&jar.state.current.get("aer")==45,"placed jar retains identity and aspect quantities");player.setItemInHand(InteractionHand.MAIN_HAND,wand);var used=WandVis.get(wand,Aspects.AIR);
        c.accept(wand.getItem().useOn(new UseOnContext(player,InteractionHand.MAIN_HAND,new BlockHitResult(p.getCenter(),Direction.UP,p,false))).consumesAction(),"wand click releases the jarred node");var released=(AuraNodeBlockEntity)level.getBlockEntity(p);
        c.accept(released.id().equals(id)&&released.state.base.get("aer")==45&&released.state.type==NodeState.Type.PURE&&WandVis.get(wand,Aspects.AIR)==used,"release preserves identity/state, costs no vis and creates no duplicate jar");level.removeBlock(p,false);
    }
    private static void aura(ServerLevel level,ServerPlayer player,BiConsumer<Boolean,String> c){
        for(var mod:NodeState.Modifier.values())for(int lock=0;lock<=2;lock++){
            var s=new NodeState();s.initialize(Map.of("aer",10));s.current.put("aer",3);s.modifier=mod;s.stabilizationLock=lock;int interval=s.rechargeInterval();
            int target=interval>0?interval:900;for(int i=0;i<target;i++)s.recharge(new Random(9),1000);
            c.accept(s.current.get("aer")==3+(interval>0?1:0),"aura recharge interval: "+mod+" / stabilizer lock "+lock);
        }
        var p=O.offset(10,2,0);var node=node(level,p,Map.of("aer",10),NodeState.Type.NORMAL,NodeState.Modifier.NONE);player.moveTo(p.getCenter());KnowledgeService.mutate(player,k->{boolean a=k.completeResearch("NODETAPPER1"),b=k.completeResearch("NODETAPPER2");return a||b;});var wand=wand();WandVis.set(wand,Aspects.AIR,9900);player.setItemInHand(InteractionHand.MAIN_HAND,wand);
        c.accept(node.charge(player,wand)&&WandVis.get(wand,Aspects.AIR)==10000&&node.state.amount(Aspects.AIR)==9,"three-vis tap near full wand removes only the one vis actually accepted");
        level.setBlockAndUpdate(p.below(),R3Content.NODE_STABILIZER.get().defaultBlockState());c.accept(node.stabilizationLock()==1,"normal stabilizer locks the node above");level.setBlockAndUpdate(p.below(),R3Content.ADVANCED_NODE_STABILIZER.get().defaultBlockState());c.accept(node.stabilizationLock()==2,"advanced stabilizer provides lock 2");level.setBlockAndUpdate(p.below().east(),Blocks.REDSTONE_BLOCK.defaultBlockState());c.accept(node.stabilizationLock()==0,"redstone disables the stabilizer");level.removeBlock(p.below().east(),false);
        node.initialize(Map.of("aer",25,"motus",49),NodeState.Type.NORMAL,NodeState.Modifier.BRIGHT);var id=node.id();level.setBlockAndUpdate(p.above(),R3Content.NODE_CONVERTER.get().defaultBlockState());level.setBlockAndUpdate(p.above().east(),Blocks.REDSTONE_BLOCK.defaultBlockState());var converter=(NodeConverterBlockEntity)level.getBlockEntity(p.above());for(int i=0;i<1001;i++)converter.serverTick();
        c.accept(level.getBlockEntity(p) instanceof EnergizedNodeBlockEntity&&converter.status()==2&&converter.progress()==1000,"powered converter energizes stabilized node after 1000 ticks");var energy=(EnergizedNodeBlockEntity)level.getBlockEntity(p);
        c.accept(energy.id().equals(id)&&energy.capacity().get("aer")==7&&energy.capacity().get("ordo")==7,"energized node reduces compounds by primal maximum then square root with brightness factor");
        c.accept(energy.consumeVis(Aspects.AIR,99)==7&&energy.consumeVis(Aspects.AIR,1)==0,"energized supply is bounded across multiple consumers in the same tick");((net.minecraft.world.level.storage.ServerLevelData)level.getLevelData()).setGameTime(level.getGameTime()+1);c.accept(energy.consumeVis(Aspects.AIR,99)==7,"energized supply renews next server tick");
        level.removeBlock(p.above().east(),false);for(int i=0;i<951;i++)converter.serverTick();c.accept(level.getBlockEntity(p) instanceof AuraNodeBlockEntity&&converter.status()==0&&converter.progress()==49,"native converter restores natural node and decrements to 49 in the same tick");var natural=(AuraNodeBlockEntity)level.getBlockEntity(p);c.accept(natural.id().equals(id)&&natural.state.base.get("motus")==49&&natural.state.current.values().stream().allMatch(n->n==0),"de-energized node retains base/type/identity and starts empty");level.removeBlock(p.above(),false);level.removeBlock(p,false);level.removeBlock(p.below(),false);
    }
